import json
from pathlib import Path


def record(identity, name, symbol, keywords, interpretation, reflection, practice, **extra):
    return dict(id=identity, name=name, symbol=symbol, keywords=keywords.split("|"),
                interpretation=interpretation, reflection=reflection, practice=practice, **extra)


