    target = Path(__file__).resolve().parents[1] / "custom_components/tarot_api/practices.json"
    target.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print({kind: len(data[kind]) for kind in ("affirmation", "oracle", "deity", "rune")})
